insert into public.guia (tema,indicacion) values ('Fuente','3_PLANO_TOPOGRAFICO_HUAJOJO_2025.pdf · agosto de 2025 · lámina 3/7.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Catálogo','61 lotes: M-A (10), M-B (22), M-C (10) y M-D (19). El código se compone con manzano y número.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Categoría','VIS según el color del plano: M-A/10 y M-B/20, 21 y 22. Los demás se registran como REGULAR.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Superficie','superficie_m2 toma el área estimada del contorno del PDF. Es aproximada hasta verificarla con SUP de QGIS o la ficha del lote.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Medidas','cota_plano_m contiene etiquetas emparejadas por posición, orientación y longitud. Revisarlas si se usarán como medida definitiva.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Orden de lados','Comienza en el vértice superior del dibujo y sigue el contorno del PDF. La referencia comercial del lado queda pendiente.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Cotas vacías','Cinco lados quedaron sin asociación segura a una cota. La longitud estimada sigue disponible.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Comercialización','Completar celdas verdes con datos verificados. Las hojas de operaciones empiezan vacías.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('SQLite','Importar urbanizaciones → manzanos → lotes → lote_lados. Usar NULL para celdas vacías. guia y cuadro_plano son de consulta.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Claves','id es interno. UNIQUE(urbanizacion_id, codigo) en manzanos y UNIQUE(manzano_id, numero) en lotes.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Importes y fechas','Importes en centavos enteros. Moneda con código ISO y fechas de operaciones en YYYY-MM-DD.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Pagos','Llenar exactamente uno de reserva_id y venta_id.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Disponibilidad','Derivar del lote habilitado, la reserva vigente y la venta vigente. El plano no aporta disponibilidad comercial.') on conflict do nothing;
insert into public.guia (tema,indicacion) values ('Dimensiones en lotes','Las columnas G:J muestran los cuatro lados en metros, junto a superficie_m2. Consulta lote_lados para ver la procedencia de cada medida.') on conflict do nothing;
